import { Component, OnInit, HostListener } from '@angular/core';
import { FormBuilder } from '@angular/forms';
import { Router, ActivatedRoute } from '@angular/router';
import { LoadingController, ToastController, AlertController } from '@ionic/angular';
// import { ReCaptchaV3Service } from 'ngx-captcha';
import { CourseService } from 'src/app/data/service/course/course.service';
import { G } from '../../../../core/common/G';
import { GAccount } from '../../../../core/common/GAccount';
import { SharedIonic } from '../../../../core/common/SharedIonic';
import { GResponse } from '../../../../core/common/GResponse';
import { CourseModel, ICourseModel } from '../../../../data/model/course/CourseModel';
import { CourseExamViewModel, ExamFinishViewModel, ICourseExamDetailViewModel, ICourseExamViewModel, UserTestQuestionAnswerViewModel, IQuestionAnswerViewModel } from '../../../../data/model/course/ExamModel';

@Component({
  selector: 'app-online-exam',
  templateUrl: './online-exam.component.html',
  styleUrls: ['./online-exam.component.scss']
})
export class OnlineExamComponent implements OnInit {

  isSubmitting = false;
  pendingAnswer: UserTestQuestionAnswerViewModel;
  siteKey = '6LdCHUsaAAAAAKMF5WYHkOzYLfLCPQT9TwnQO-uX';
  windowWidth = 1000;
  course: ICourseModel;
  exam: ICourseExamViewModel;
  examDetail: ICourseExamDetailViewModel;
  isLoading = true;
  isFinish = false;
  currentQuestionIndex = 0;
  currentQuestionNumber = 0;
  timeLeft = 0;
  timeSpend = 0;
  selectedAnswerIndex = -1;
  currentMinute = '00';
  currentSecond = '00';
  timer;
  trueAnswerCount = 0;
  falseAnswerCount = 0;
  mainQuestion: IQuestionAnswerViewModel[];
  connectionLost = false;

  constructor(
    private router: Router,
    private activatedRoute: ActivatedRoute,
    private courseService: CourseService,
    public loadingController: LoadingController,
    public toastController: ToastController,
    public alertController: AlertController,
    // private reCaptchaV3Service: ReCaptchaV3Service,
    private fb: FormBuilder) {

    G.getWindowWidth().subscribe(
      res => {
        this.windowWidth = res;
      }
    );
  }

  ngOnInit(): void {
  }

  selectAnswer(index: number): void {
    if (this.isSubmitting || this.pendingAnswer) return;
    this.selectedAnswerIndex = index;
    this.saveProgress();
  }

  private get progressKey(): string {
    return 'avalamooz-exam-' + this.examDetail.examId;
  }

  private saveProgress(): void {
    if (!this.examDetail || this.isFinish) return;
    const question = this.examDetail.questions[this.currentQuestionIndex];
    if (!question) return;
    try {
      sessionStorage.setItem(this.progressKey, JSON.stringify({
        questionId: question.question.id,
        answerId: question.tests[this.selectedAnswerIndex]?.id,
        remaining: +this.currentMinute * 60 + +this.currentSecond,
        pending: this.pendingAnswer
      }));
    } catch { /* The exam remains usable when browser storage is unavailable. */ }
  }

  @HostListener('window:online')
  onOnline(): void {
    if (this.connectionLost) this.onRefresh();
  }

  onCheckLeftTime(date1: Date, sec: number) {

    // let date1 = new Date(this.course.createDate);

    const date2 = new Date();

    let diff = date2.getTime() - new Date(date1).getTime();

    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    diff -= days * (1000 * 60 * 60 * 24);

    const hours = Math.floor(diff / (1000 * 60 * 60));
    diff -= hours * (1000 * 60 * 60);

    const mins = Math.floor(diff / (1000 * 60));
    diff -= mins * (1000 * 60);

    const seconds = Math.floor(diff / (1000));
    diff -= seconds * (1000);

    const totalSec = (mins * 60) + seconds;

    if (days == 0 && hours == 0 && totalSec < sec) {

      return true;
    } else {

      return false;
    }
  }

  calculateTimer(): void {

    clearInterval(this.timer);
    const seconds = this.timeLeft;
    this.currentMinute = Math.floor(seconds / 60).toString().padStart(2, '0');
    this.currentSecond = (seconds % 60).toString().padStart(2, '0');
    this.saveProgress();

    this.timer = setInterval(e => {

      if (+this.currentSecond > 0) {

        const s = (+this.currentSecond - 1);

        if (s > 9) {
          this.currentSecond = s.toString();
        } else {
          this.currentSecond = '0' + s.toString();
        }

      } else if (+this.currentMinute > 0) {

        const m = (+this.currentMinute - 1);
        this.currentSecond = '59';

        if (m > 9) {
          this.currentMinute = m.toString();
        } else {
          this.currentMinute = '0' + m.toString();
        }
      } else {
        clearInterval(this.timer);
        this.onNextQuestion();
      }
      this.saveProgress();

    }, 1000);
  }

  onNextQuestion(): void {

    if (this.isSubmitting || this.isLoading || this.isFinish) return;
    this.isSubmitting = true;
    SharedIonic.loading(this.loadingController);
    clearInterval(this.timer);
    this.timeLeft = +this.currentMinute * 60 + +this.currentSecond;
    this.timeSpend = this.examDetail.questions[this.currentQuestionIndex].question.time - this.timeLeft;
    if (!this.pendingAnswer) {
      const question = this.examDetail.questions[this.currentQuestionIndex];
      const answerId = question.tests[this.selectedAnswerIndex]?.id || 0;
      this.pendingAnswer = new UserTestQuestionAnswerViewModel(
        0, this.examDetail.examId, answerId, this.timeSpend, this.timeLeft, question.question.id);
    }
    this.saveProgress();
    this.courseService.SetExamTestAnswer(this.pendingAnswer
    ).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          this.examDetail.userTestQuestionAnswers.push(this.pendingAnswer);
          this.pendingAnswer = null;
          this.connectionLost = false;
          this.isSubmitting = false;
          try { sessionStorage.removeItem(this.progressKey); } catch {}

          if (this.examDetail.questions.length <= this.currentQuestionIndex + 1) {

            this.isFinish = true;
            SharedIonic.dismissLoading(this.loadingController);
            this.finishExam();
            return;
          } else {
            this.currentQuestionIndex++;
            this.currentQuestionNumber++;
            this.selectedAnswerIndex = -1;

            this.timeLeft = this.examDetail.questions[this.currentQuestionIndex].question.time;
            this.calculateTimer();

            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.toast(this.toastController, 'خطا - پاسخ درج نشد');
          this.isSubmitting = false;
          this.connectionLost = true;
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
        this.isSubmitting = false;
        this.connectionLost = true;
      }
    );
  }

  ionViewWillLeave() {

    this.saveProgress();
    clearInterval(this.timer);
  }

  finishExam() {

    if (this.isSubmitting) return;
    this.isSubmitting = true;

    this.trueAnswerCount = 0;
    this.falseAnswerCount = 0;

    this.examDetail.userTestQuestionAnswers.forEach(answer => {

      const question = this.mainQuestion.find(e => e.question.id == answer.examQuestionId);

      if (question != null) {

        question.tests.find(e => e.isActive && e.isTrue).id == answer.examTestQuestionAnswerId ? this.trueAnswerCount++ : this.falseAnswerCount++;
      }
    });

    if (this.trueAnswerCount >= 10) {

      this.examDetail.isPass = true;
    } else {
      this.examDetail.isPass = false;
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.SetExamEnd(
      new ExamFinishViewModel(
        this.examDetail.examId,
        this.examDetail.isPass,
        this.trueAnswerCount
      )
    ).subscribe(
      res => {
        this.isSubmitting = false;
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          this.connectionLost = false;
          try { sessionStorage.removeItem(this.progressKey); } catch {}
          SharedIonic.toast(this.toastController, 'آزمون شما اتمام یافت');
        } else {
          this.connectionLost = true;
          SharedIonic.toast(this.toastController, 'خطا - آزمون اتمام نیافت');
        }
      },
      err => {
        this.isSubmitting = false;
        SharedIonic.dismissLoading(this.loadingController);
        this.connectionLost = true;
        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
      }
    );
  }

  ionViewDidLeave() {

    clearInterval(this.timer);
  }

  onRefresh() {

    if (this.isSubmitting) return;
    if (this.isFinish) { this.finishExam(); return; }
    if (this.pendingAnswer) { this.onNextQuestion(); return; }
    this.ionViewWillEnter();
  }

  getPercent(courseId: number): number {

    let trueCount = 0;
    let falseCount = 0;

    this.examDetail.userTestQuestionAnswers.forEach(answer => {

      const question = this.mainQuestion.find(e => e.question.id == answer.examQuestionId);

      if (question != null) {

        if (question.question.courseId == courseId) {

          question.tests.find(e => e.isActive && e.isTrue).id == answer.examTestQuestionAnswerId ? trueCount++ : falseCount++;
        }
      }
    });

    return ((trueCount * 100) / (trueCount + falseCount));
  }

  ionViewWillEnter() {

    clearInterval(this.timer);

    const params = this.activatedRoute.snapshot.params;
    {

      this.connectionLost = false;
      this.isLoading = true;
      this.isFinish = false;
      this.currentQuestionIndex = 0;
      this.currentQuestionNumber = 0;
      this.pendingAnswer = null;
      this.selectedAnswerIndex = -1;

      const id = params.id;

      if (id === undefined || id == null || +id <= 0) {

        this.router.navigateByUrl('/Exam');
      } else {

        SharedIonic.loading(this.loadingController);

        this.courseService.GetExamByIdForBegin(+id).subscribe(
          res => {
            SharedIonic.dismissLoading(this.loadingController);
            if (res.status === GResponse.SuccessStatus) {

              this.course = new CourseModel(
                res.data.courseId,
                res.data.courseName,
                res.data.coursePrice,
                res.data.courseOffPrice,
                0,
                '',
                '',
                res.data.imageUrl,
                '',
                new Date(),
                new Date(),
                [],
                true);

              this.exam = new CourseExamViewModel(
                res.data.examId,
                res.data.isPass,
                res.data.isDone,
                res.data.isStart,
                res.data.isPay,
                res.data.level,
                res.data.title,
                res.data.description,
                res.data.point,
                res.data.startTime,
                res.data.endTime,
                res.data.courseId,
                res.data.courseName,
                res.data.coursePrice,
                res.data.courseOffPrice,
                res.data.imageUrl,
                res.data.freeExamCount,
                res.data.requestExamCount,
                res.data.examPrice,
                res.data.examLevelCount
              );

              this.examDetail = res.data;

              this.mainQuestion = [...this.examDetail.questions];

              const answeredIds = new Set(this.examDetail.userTestQuestionAnswers.map(answer => answer.examQuestionId));
              this.examDetail.questions = this.mainQuestion.filter(question => !answeredIds.has(question.question.id));
              this.currentQuestionNumber = this.mainQuestion.length - this.examDetail.questions.length;

              if (this.examDetail.questions.length > 0) {

                this.timeLeft = this.examDetail.questions[0].question.time;
                try {
                  const saved = JSON.parse(sessionStorage.getItem(this.progressKey));
                  const question = this.examDetail.questions[0];
                  if (saved && saved.questionId === question.question.id) {
                    this.selectedAnswerIndex = question.tests.findIndex(test => test.id === saved.answerId);
                    if (Number.isFinite(saved.remaining)) this.timeLeft = Math.max(0, Math.min(this.timeLeft, saved.remaining));
                    if (saved.pending?.examId === this.examDetail.examId && saved.pending?.examQuestionId === question.question.id) {
                      this.pendingAnswer = saved.pending;
                    }
                  }
                } catch {}
                this.isLoading = false;
                if (this.pendingAnswer) {
                  this.currentMinute = Math.floor(this.timeLeft / 60).toString().padStart(2, '0');
                  this.currentSecond = (this.timeLeft % 60).toString().padStart(2, '0');
                  this.onNextQuestion();
                } else {
                  this.calculateTimer();
                }
              } else {
                this.isFinish = true;
                this.finishExam();
                this.isLoading = false;
              }
            }
            else {
              SharedIonic.toast(this.toastController, 'امکان آزمون وجود ندارد');
              this.router.navigateByUrl('/Exam');
            }
          },
          err => {
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
            this.connectionLost = true;
          }
        );
      }
    }
  }
}
